CREATE TABLE IF NOT EXISTS v21_learning(user_id text NOT NULL REFERENCES users(id),item_id text NOT NULL,kind text NOT NULL,data jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,item_id,kind));
CREATE TABLE IF NOT EXISTS v21_tasks(id uuid PRIMARY KEY,class_id text NOT NULL REFERENCES classes(id),creator text NOT NULL REFERENCES users(id),title text NOT NULL,scenario text NOT NULL,unit integer NOT NULL,source jsonb NOT NULL,status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','closed')),due_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS v21_attempts(id uuid PRIMARY KEY,task_id uuid NOT NULL REFERENCES v21_tasks(id),student_id text NOT NULL REFERENCES users(id),ordinal integer NOT NULL CHECK(ordinal IN (1,2)),answers jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','grading','review','graded')),marks jsonb NOT NULL DEFAULT '[]',score numeric,note text NOT NULL DEFAULT '',error text NOT NULL DEFAULT '',lease_token text,lease_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),submitted_at timestamptz,graded_at timestamptz,UNIQUE(task_id,student_id,ordinal));
CREATE TABLE IF NOT EXISTS v21_events(id uuid PRIMARY KEY,task_id uuid REFERENCES v21_tasks(id),attempt_id uuid REFERENCES v21_attempts(id),actor_id text NOT NULL,action text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS v21_tasks_class ON v21_tasks(class_id,created_at);
CREATE INDEX IF NOT EXISTS v21_attempts_student ON v21_attempts(student_id,task_id);
